
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_hjs_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_hjs_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.241448142550747e+00, -4.159735918330324e+00, -4.045347557832553e+00, -3.887122219922753e+00, -3.672005143289226e+00, -3.386717762152330e+00, -3.021629980813334e+00, -2.577571445353868e+00, -2.074121738370606e+00, -1.548327729268111e+00, -1.025361087460471e+00, -6.479528362709940e-01, -5.415407944138843e-01, -4.403330203504121e-01, -3.093856792235922e-01, -1.823637690295982e-01, -7.608795116309833e-02, -8.527030991604739e-03, -3.783175601277447e-05, -4.926777900899020e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


